-- ============================================
-- ROLES: roles ("admin" ve todo y la configuración)
-- ============================================
CREATE TABLE IF NOT EXISTS "ROLES" (
    "ID_ROL" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_ROLES" PRIMARY KEY,
    "NOMBRE_ROL" VARCHAR(50) NOT NULL CONSTRAINT "UQ_ROLES_NOMBRE" UNIQUE,
    "DESCRIPCION" VARCHAR(200) NULL,
    "NIVEL_ACCESO" INT NOT NULL DEFAULT 1,
    "ES_SISTEMA" BOOLEAN NOT NULL DEFAULT FALSE,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);
